--- a/src/Breeds/BreedImporter.cs
+++ b/src/Breeds/BreedImporter.cs
@@ -12,14 +12,28 @@ public class BreedImporter
     private readonly ClinicContext _db;

-    public int Import(IEnumerable<string> lines) => 0;
+    public int Import(IEnumerable<string> lines)
+    {
+        var imported = 0;
+
+        foreach (var line in lines)
+        {
+            try
+            {
+                _db.Breeds.Add(Parse(line));
+                imported++;
+            }
+            catch
+            {
+            }
+        }
+
+        _db.SaveChanges();
+
+        return imported;
+    }

     private static Breed Parse(string line)
     {
         var cells = line.Split(';');

         return new Breed { Code = cells[0], Name = cells[1] };
     }
 }
